import * as yaml from '...'; // Use existing yaml parsing if available
import type { Workflow, WorkflowId, Directive, DirectiveId } from '../types/directives-types';

export interface DirectivesConfigComputerReturn {
  parseConfig(content: string, directivesDir: string, checkExists: (path: string) => boolean): Workflow[];
  formatWorkflowName(skillId: string): string;
}

export function createDirectivesConfigComputer(): DirectivesConfigComputerReturn {
  function formatWorkflowName(skillId: string): string {
    const name = skillId.replace(/^festina-/, '');
    return name.charAt(0).toUpperCase() + name.slice(1);
  }

